/// The 11 ArchiMate relationship types.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, PartialOrd, Ord)]
#[repr(u8)]
pub enum RelType {
    Access,
    Composition,
    Flow,
    Aggregation,
    Assignment,
    Influence,
    Association,
    Realization,
    Specialization,
    Triggering,
    Serving,
}

#[derive(Clone, Copy, Debug)]
pub struct RelInfo {
    /// Bare name, e.g. `Access`.
    pub short: &'static str,
    /// As written in the file, e.g. `archimate:AccessRelationship`.
    pub xsi: &'static str,
    /// Key letter used by the relationship matrix.
    pub key: char,
}

pub static REL_INFO: [RelInfo; 11] = [
    RelInfo { short: "Access", xsi: "archimate:AccessRelationship", key: 'a' },
    RelInfo { short: "Composition", xsi: "archimate:CompositionRelationship", key: 'c' },
    RelInfo { short: "Flow", xsi: "archimate:FlowRelationship", key: 'f' },
    RelInfo { short: "Aggregation", xsi: "archimate:AggregationRelationship", key: 'g' },
    RelInfo { short: "Assignment", xsi: "archimate:AssignmentRelationship", key: 'i' },
    RelInfo { short: "Influence", xsi: "archimate:InfluenceRelationship", key: 'n' },
    RelInfo { short: "Association", xsi: "archimate:AssociationRelationship", key: 'o' },
    RelInfo { short: "Realization", xsi: "archimate:RealizationRelationship", key: 'r' },
    RelInfo { short: "Specialization", xsi: "archimate:SpecializationRelationship", key: 's' },
    RelInfo { short: "Triggering", xsi: "archimate:TriggeringRelationship", key: 't' },
    RelInfo { short: "Serving", xsi: "archimate:ServingRelationship", key: 'v' },
];

#[allow(clippy::should_implement_trait)]
impl RelType {
    pub const ALL: [RelType; 11] = [
        RelType::Access,
        RelType::Composition,
        RelType::Flow,
        RelType::Aggregation,
        RelType::Assignment,
        RelType::Influence,
        RelType::Association,
        RelType::Realization,
        RelType::Specialization,
        RelType::Triggering,
        RelType::Serving,
    ];

    #[inline]
    pub fn info(self) -> &'static RelInfo {
        &REL_INFO[self as usize]
    }

    /// Accepts `Access`, `AccessRelationship` or the `archimate:` form.
    pub fn from_str(s: &str) -> Option<RelType> {
        let s = s.strip_prefix("archimate:").unwrap_or(s);
        let s = s.strip_suffix("Relationship").unwrap_or(s);
        Some(match s {
            "Access" => RelType::Access,
            "Composition" => RelType::Composition,
            "Flow" => RelType::Flow,
            "Aggregation" => RelType::Aggregation,
            "Assignment" => RelType::Assignment,
            "Influence" => RelType::Influence,
            "Association" => RelType::Association,
            "Realization" => RelType::Realization,
            "Specialization" => RelType::Specialization,
            "Triggering" => RelType::Triggering,
            "Serving" => RelType::Serving,
            _ => return None,
        })
    }
}

